// @vitest-environment node
/**
 * Golden fixture tests (spec §10.2 T01–T04) on PDFs generated by
 * scripts/fixtures/make-pdf-fixtures.mjs, loaded with the real pdfjs-dist
 * (legacy build, in-thread worker) → pageInput → extract.
 */
import { afterAll, describe, expect, it } from 'vitest';
import type { Block } from '../../ipc/generated/Block';
import { sha256Hex } from '../../domain/canonicalJson';
import { cssPointToPdf, hitTest, pdfRectToCss } from './coords';
import { extractPage } from './extract';
import { buildPageInput, PDF_OPS } from './pageInput';
import { applyRunningUpdates, detectRunningElements } from './running';
import { loadPdfjsLegacy, openFixture, readFixtureJson, type ExpectedBlock, type ExpectedFixture } from './testing/fixtures';
import type { PdfPageResult } from './types';

const FIXTURES = ['single-column', 'two-column', 'table-formula', 'rotated', 'cropbox', 'scan', 'unmapped'] as const;

async function extractFixture(name: string) {
  const doc = await openFixture(`${name}.pdf`);
  const pages: PdfPageResult[] = [];
  const pdfPages = [];
  for (let i = 1; i <= doc.numPages; i++) {
    const page = await doc.getPage(i);
    pdfPages.push(page);
    pages.push(await extractPage(await buildPageInput(page), `fixture:${name}`, { sha256Hex }));
  }
  applyRunningUpdates(pages, detectRunningElements(pages));
  const expected = await readFixtureJson<ExpectedFixture>(`${name}.expected.json`);
  return { pages, pdfPages, expected };
}

const squash = (s: string) => s.replace(/\s+/g, ' ').trim();

function matches(b: Block, e: ExpectedBlock): boolean {
  if (e.raw) return b.rawText === e.text;
  if (e.matchPrefix) return b.kind === e.kind && b.sourceText.startsWith(e.matchPrefix);
  return squash(b.sourceText) === squash(e.text);
}

interface Metrics {
  expected: number;
  extracted: number;
  matched: number;
  orderPairs: number;
  orderCorrect: number;
  kindCorrect: number;
}

const totals: Record<string, Metrics> = {};

function score(name: string, blocks: Block[], expected: ExpectedBlock[]): { pairs: [Block, ExpectedBlock, number][] } {
  const used = new Set<number>();
  const pairs: [Block, ExpectedBlock, number][] = [];
  for (const b of blocks) {
    const ei = expected.findIndex((e, i) => !used.has(i) && matches(b, e));
    if (ei >= 0) {
      used.add(ei);
      pairs.push([b, expected[ei]!, ei]);
    }
  }
  let orderPairs = 0;
  let orderCorrect = 0;
  for (let i = 0; i < pairs.length; i++) {
    for (let j = i + 1; j < pairs.length; j++) {
      orderPairs++;
      if (pairs[i]![2] < pairs[j]![2]) orderCorrect++;
    }
  }
  const m = (totals[name] ??= { expected: 0, extracted: 0, matched: 0, orderPairs: 0, orderCorrect: 0, kindCorrect: 0 });
  m.expected += expected.length;
  m.extracted += blocks.length;
  m.matched += pairs.length;
  m.orderPairs += orderPairs;
  m.orderCorrect += orderCorrect;
  m.kindCorrect += pairs.filter(([b, e]) => b.kind === e.kind).length;
  return { pairs };
}

/** A picture region of the page: a figure block without text. */
const isPicture = (b: Block) => b.kind === 'figure' && b.sourceText === '';

function bbox(b: Block): [number, number, number, number] {
  if (b.location.kind !== 'pdf') throw new Error('not pdf');
  const r = b.location.rects;
  return [
    Math.min(...r.map((x) => x.x)),
    Math.min(...r.map((x) => x.y)),
    Math.max(...r.map((x) => x.x + x.width)),
    Math.max(...r.map((x) => x.y + x.height)),
  ];
}

describe.each(FIXTURES)('fixture %s', (name) => {
  it('matches the golden paragraph order, kinds, roles, policies and rects', async () => {
    const { pages, expected } = await extractFixture(name);
    for (const ep of expected.pages) {
      const all = pages[ep.pageIndex]!;
      expect(all.blocks.every((b) => b.location.kind === 'pdf' && b.location.pageIndex === ep.pageIndex)).toBe(true);
      // The golden files list text blocks; picture regions are checked on their own below.
      const page = { ...all, blocks: all.blocks.filter((b) => !isPicture(b)) };
      const { pairs } = score(name, page.blocks, ep.blocks);
      // T01/T02: every expected block is found, in the same order
      expect(pairs.map((p) => p[2]), `${name} p${ep.pageIndex} order`).toEqual(ep.blocks.map((_, i) => i));
      expect(page.blocks.length, `${name} p${ep.pageIndex} no extra blocks`).toBe(ep.blocks.length);
      for (const [b, e] of pairs) {
        expect(b.kind, `${name}: kind of "${e.text.slice(0, 30)}"`).toBe(e.kind);
        for (const role of e.roles ?? []) expect(b.roles, `${name}: roles of "${e.text.slice(0, 30)}"`).toContain(role);
        if (e.policy) expect(b.translationPolicy, `${name}: policy of "${e.text.slice(0, 30)}"`).toBe(e.policy);
        if (b.location.kind === 'pdf') expect(b.location.rects.length).toBe(e.lines);
        const [x0, y0, x1, y1] = bbox(b);
        const tol = 8;
        expect(Math.abs(x0 - e.rect[0]), `${name}: x0 "${e.text.slice(0, 20)}"`).toBeLessThan(tol);
        expect(Math.abs(y0 - e.rect[1]), `${name}: y0 "${e.text.slice(0, 20)}"`).toBeLessThan(tol);
        expect(Math.abs(x1 - e.rect[2]), `${name}: x1 "${e.text.slice(0, 20)}"`).toBeLessThan(tol + 0.03 * (e.rect[2] - e.rect[0]));
        expect(Math.abs(y1 - e.rect[3]), `${name}: y1 "${e.text.slice(0, 20)}"`).toBeLessThan(tol);
      }
    }
  });
});

describe('T01 single column with title and footnote', () => {
  it('reads title → headings → paragraphs → footnote; header/footer are running elements', async () => {
    const { pages } = await extractFixture('single-column');
    const p0 = pages[0]!.blocks;
    expect(p0.map((b) => b.kind)).toEqual(['paragraph', 'heading', 'heading', 'paragraph', 'paragraph', 'paragraph', 'paragraph']);
    expect(p0[0]!.roles).toContain('running_header');
    expect(p0[5]!.roles).toEqual(['footnote']);
    expect(p0[6]!.roles).toContain('running_footer');
    for (const p of pages) {
      const running = p.blocks.filter((b) => b.roles.includes('running_header') || b.roles.includes('running_footer'));
      expect(running).toHaveLength(2);
      expect(running.every((b) => b.translationPolicy === 'preserve')).toBe(true);
    }
    // superscript marker stays on its line; hyphenation removed and mapped
    expect(p0[3]!.sourceText).toContain('and nothing1 in the format');
    expect(p0[4]!.sourceText).toContain('the reconstruction has');
    expect(p0[4]!.mapping.offsets.some((o) => o.sourceStart === o.sourceEnd && o.rawEnd - o.rawStart === 2)).toBe(true);
    expect(pages[1]!.blocks[2]!.sourceText).toContain('such as Thoth-Reader keep');
    // continuation candidate is flagged, not merged
    expect(pages[1]!.blocks.find((b) => b.roles.includes('continues_on_next_page'))?.sourceText.endsWith('into')).toBe(true);
    expect(pages[2]!.blocks[1]!.sourceText.startsWith('one block.')).toBe(true);
  });
});

describe('pictures', () => {
  it('turns the image of the two-column fixture into a preserved figure block in reading order', async () => {
    const { pages } = await extractFixture('two-column');
    const pics = pages.flatMap((p) => p.blocks.filter(isPicture));
    expect(pics.length).toBeGreaterThan(0);
    for (const b of pics) {
      expect(b.translationPolicy).toBe('preserve');
      expect(b.content).toEqual([]);
      expect(b.location.kind === 'pdf' && b.location.rects.length).toBe(1);
      const [x0, y0, x1, y1] = bbox(b);
      expect(x1 - x0).toBeGreaterThanOrEqual(40);
      expect(y1 - y0).toBeGreaterThanOrEqual(40);
      // it sits between text: not the first block of its page
      const page = pages.find((p) => p.blocks.includes(b))!;
      expect(page.blocks.indexOf(b)).toBeGreaterThan(0);
      // ids stay unique
      expect(new Set(page.blocks.map((x) => x.id)).size).toBe(page.blocks.length);
    }
  });
});

describe('T02 two columns, table and formula', () => {
  it('never mixes columns and keeps all body blocks high quality', async () => {
    const { pages, expected } = await extractFixture('two-column');
    for (const [pi, p] of pages.entries()) {
      for (const b of p.blocks.filter((x) => !isPicture(x))) {
        // a block is either fully in the left column, fully in the right, or a spanning element
        const [x0, , x1] = bbox(b);
        const spans = x0 < 297 && x1 > 315;
        const golden = expected.pages[pi]!.blocks.find((e) => squash(e.text) === squash(b.sourceText))!;
        expect(golden, b.sourceText).toBeDefined();
        if (spans) expect(golden.rect[0] < 297 && golden.rect[2] > 315).toBe(true);
        expect(b.quality.level).toBe('high');
      }
      expect(p.diagnostics.columnCount).toBe(2);
    }
  });

  it('table, formula and code are preserved and never auto-translated', async () => {
    const { pages } = await extractFixture('table-formula');
    const blocks = pages[0]!.blocks;
    const preserved = blocks.filter((b) => ['table', 'formula', 'code'].includes(b.kind));
    expect(preserved.map((b) => b.kind)).toEqual(['table', 'formula', 'code']);
    expect(preserved.every((b) => b.translationPolicy === 'preserve')).toBe(true);
    expect(blocks.find((b) => b.kind === 'caption')?.translationPolicy).toBe('auto');
    expect(blocks.find((b) => b.kind === 'code')!.rawText).toBe('function add(a, b) {\n    return a + b;\n}');
  });
});

describe('T03 scan and unmapped glyphs', () => {
  it('scan page: original kept, zero blocks, zero automatic translation', async () => {
    const { pages } = await extractFixture('scan');
    expect(pages[0]!.blocks).toEqual([]);
    expect(pages[0]!.diagnostics.reasons).toEqual(['likely_scan']);
    expect(pages[0]!.diagnostics.imageCount).toBe(1);
    expect(pages[0]!.diagnostics.imageCoverage).toBe(1);
  });

  it('unmapped glyph page: zero automatic translation', async () => {
    const { pages } = await extractFixture('unmapped');
    const blocks = pages[0]!.blocks;
    expect(blocks.length).toBeGreaterThan(0);
    expect(blocks.filter((b) => b.translationPolicy === 'auto')).toEqual([]);
    expect(blocks.every((b) => b.quality.level === 'low' && b.quality.reasons.includes('missing_unicode'))).toBe(true);
    expect(pages[0]!.diagnostics.translatableBlockCount).toBe(0);
  });
});

describe('T04 rotation, crop and high zoom', () => {
  it('clicking the centre of each golden rect hits the block with that text', async () => {
    for (const name of ['rotated', 'cropbox'] as const) {
      const { pages, pdfPages, expected } = await extractFixture(name);
      for (const ep of expected.pages) {
        const page = pdfPages[ep.pageIndex]!;
        for (const scale of [1, 4]) {
          const vp = page.getViewport({ scale });
          for (const e of ep.blocks) {
            const [x0, y0, x1, y1] = e.rect;
            const css = pdfRectToCss({ x: x0, y: y0, width: x1 - x0, height: y1 - y0 }, vp);
            const p = cssPointToPdf(css.left + css.width / 2, css.top + css.height / 2, vp);
            const hit = hitTest(pages[ep.pageIndex]!.blocks, p, 2);
            expect(hit && squash(hit.sourceText), `${name} p${ep.pageIndex} @${scale}`).toBe(squash(e.text));
          }
        }
      }
    }
  });
});

describe('pdf.js integration details', () => {
  it('OPS codes used for image detection match the installed pdf.js', async () => {
    const pdfjs = await loadPdfjsLegacy();
    for (const [k, v] of Object.entries(PDF_OPS)) expect((pdfjs.OPS as Record<string, number>)[k], k).toBe(v);
  });

  it('page input carries real font names (fontExtraProperties)', async () => {
    const doc = await openFixture('table-formula.pdf');
    const input = await buildPageInput(await doc.getPage(1));
    const names = Object.values(input.styles).map((s) => s.fontName);
    expect(names).toEqual(expect.arrayContaining(['Helvetica-Bold', 'Times-Roman', 'Courier']));
  });
});

afterAll(() => {
  const rows = Object.entries(totals).map(([name, m]) => ({
    fixture: name,
    expected: m.expected,
    extracted: m.extracted,
    precision: m.extracted ? +(m.matched / m.extracted).toFixed(3) : 1,
    recall: m.expected ? +(m.matched / m.expected).toFixed(3) : 1,
    orderPairAccuracy: m.orderPairs ? +(m.orderCorrect / m.orderPairs).toFixed(3) : 1,
    kindAccuracy: m.matched ? +(m.kindCorrect / m.matched).toFixed(3) : 1,
  }));
  if (rows.length) console.table(rows);
});
